// Keycloak plugin: four entities (Server, Realm, Client, RedirectUrl) + real
// Keycloak Admin API management. A local HTTP server stands in for Keycloak
// (its URL is simply the server_url of the created KeycloakServer), so no real
// Keycloak is needed. Verifies:
//   - creating a Server auto-discovers realms (master skipped) and clients
//     (built-ins filtered) with their secrets, and mirrors their URIs
//   - creating a Realm/Client really creates it in Keycloak (confidential
//     OIDC client, secret generated by Keycloak and stored locally)
//   - renaming and deleting a Realm/Client propagates to Keycloak
//   - regenerate-secret asks Keycloak for a new secret and stores it
//   - register/ + unregister/: instance URL sync (idempotent, both kinds)
//   - the mirror follows Keycloak on reads
//   - deleting the Server only removes the local mirror (Keycloak untouched)
// Run: node --test test/keycloak.test.mjs
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import { readFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { SqliteDb } from '../dist/db/sqlite.js';
import { createApiServer } from '../dist/api/server.js';
import { loadPlugins } from '../dist/plugins/runtime.js';
import keycloakPlugin from '../dist/plugins/keycloak/index.js';

const ROOT = join(fileURLToPath(import.meta.url), '..', '..');
const DB = join(ROOT, 'test', '.keycloak.sqlite');
let db, server, base, kc, kcBase;

const POST_LOGOUT_ATTR = 'post.logout.redirect.uris';

// Mutable stand-in Keycloak state: writes from paasbox update it, reads serve it.
let uuidSeq = 0;
const kcState = {
  realms: ['master', 'curioo'],
  clients: {
    curioo: [
      {
        id: 'uuid-curio',
        clientId: 'curio-city',
        publicClient: false,
        secret: 'pre-existing-secret',
        redirectUris: ['https://old.example.com/cb'],
        attributes: { [POST_LOGOUT_ATTR]: 'https://old.example.com' },
      },
      // Built-in clients must be ignored by discovery
      { id: 'uuid-account', clientId: 'account', publicClient: true, redirectUris: [] },
      { id: 'uuid-admincli', clientId: 'admin-cli', publicClient: true, redirectUris: [] },
    ],
  },
};
const clientByUuid = (realm, id) => kcState.clients[realm]?.find((c) => c.id === id);

const api = (m, p, b) =>
  fetch(`${base}${p}`, {
    method: m,
    headers: b ? { 'Content-Type': 'application/json' } : undefined,
    body: b ? JSON.stringify(b) : undefined,
  }).then(async (r) => ({ status: r.status, body: await r.json().catch(() => null) }));

// stand-in Keycloak (token endpoint + the Admin API subset the plugin uses)
function startKeycloak() {
  kc = http.createServer((req, res) => {
    let raw = '';
    req.on('data', (c) => (raw += c));
    req.on('end', () => {
      res.setHeader('content-type', 'application/json');
      const url = new URL(req.url, 'http://x');
      const path = url.pathname;
      const body = () => JSON.parse(raw || '{}');

      if (req.method === 'POST' && path === '/realms/master/protocol/openid-connect/token') {
        return res.end(
          JSON.stringify({ access_token: 'test-token', expires_in: 300, token_type: 'Bearer' }),
        );
      }
      if (req.method === 'GET' && path === '/admin/realms') {
        return res.end(JSON.stringify(kcState.realms.map((r) => ({ realm: r, enabled: true }))));
      }
      if (req.method === 'POST' && path === '/admin/realms') {
        kcState.realms.push(body().realm);
        res.writeHead(201);
        return res.end();
      }
      let m = path.match(/^\/admin\/realms\/([^/]+)$/);
      if (req.method === 'PUT' && m) {
        const idx = kcState.realms.indexOf(m[1]);
        if (idx === -1) {
          res.writeHead(404);
          return res.end('{}');
        }
        const newName = body().realm;
        kcState.realms[idx] = newName;
        kcState.clients[newName] = kcState.clients[m[1]] ?? [];
        if (newName !== m[1]) delete kcState.clients[m[1]];
        res.writeHead(204);
        return res.end();
      }
      if (req.method === 'DELETE' && m) {
        const idx = kcState.realms.indexOf(m[1]);
        if (idx === -1) {
          res.writeHead(404);
          return res.end('{}');
        }
        kcState.realms.splice(idx, 1);
        delete kcState.clients[m[1]];
        res.writeHead(204);
        return res.end();
      }
      m = path.match(/^\/admin\/realms\/([^/]+)\/clients$/);
      if (req.method === 'GET' && m) {
        let clients = kcState.clients[m[1]] ?? [];
        const wanted = url.searchParams.get('clientId');
        if (wanted) clients = clients.filter((c) => c.clientId === wanted);
        return res.end(JSON.stringify(clients));
      }
      if (req.method === 'POST' && m) {
        const rep = body();
        const created = {
          ...rep,
          id: `uuid-${++uuidSeq}`,
          // Keycloak generates a secret for confidential clients
          secret: rep.publicClient ? undefined : `generated-secret-${uuidSeq}`,
        };
        (kcState.clients[m[1]] ??= []).push(created);
        res.writeHead(201, { Location: `/admin/realms/${m[1]}/clients/${created.id}` });
        return res.end();
      }
      m = path.match(/^\/admin\/realms\/([^/]+)\/clients\/([^/]+)\/client-secret$/);
      if (m) {
        const client = clientByUuid(m[1], m[2]);
        if (!client) {
          res.writeHead(404);
          return res.end('{}');
        }
        if (req.method === 'POST') client.secret = `regenerated-${++uuidSeq}`;
        return res.end(JSON.stringify({ type: 'secret', value: client.secret }));
      }
      m = path.match(/^\/admin\/realms\/([^/]+)\/clients\/([^/]+)$/);
      if (m) {
        const client = clientByUuid(m[1], m[2]);
        if (!client) {
          res.writeHead(404);
          return res.end('{}');
        }
        if (req.method === 'GET') return res.end(JSON.stringify(client));
        if (req.method === 'PUT') {
          Object.assign(client, body());
          res.writeHead(204);
          return res.end();
        }
        if (req.method === 'DELETE') {
          const list = kcState.clients[m[1]];
          list.splice(list.indexOf(client), 1);
          res.writeHead(204);
          return res.end();
        }
      }
      res.writeHead(404);
      res.end('{}');
    });
  });
  return new Promise((r) => kc.listen(0, '127.0.0.1', () => r()));
}

before(async () => {
  await startKeycloak();
  kcBase = `http://127.0.0.1:${kc.address().port}`;

  rmSync(DB, { force: true });
  db = new SqliteDb(DB);
  db.exec(readFileSync(join(ROOT, 'datamodel', 'sql', 'schema.sqlite.sql'), 'utf8'));
  await loadPlugins(db, [keycloakPlugin]); // creates plugin tables + registers entities
  server = createApiServer({ db });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  base = `http://127.0.0.1:${server.address().port}`;
});
after(async () => {
  await new Promise((r) => server.close(r));
  await new Promise((r) => kc.close(r));
  await db.close();
  rmSync(DB, { force: true });
});

let serverId, curiooRealmId, curioClientRowId, newRealmId, newClientRowId;

test('creating a Server auto-discovers realms, clients and their secrets', async () => {
  const s = await api('POST', '/api/plugins/keycloak/servers/', {
    name: 'kc-e2e',
    server_url: kcBase,
    admin_username: 'admin',
    admin_password: 'admin',
  });
  assert.equal(s.status, 201);
  serverId = s.body.id;
  assert.deepEqual(s.body.discovered, ['curioo', 'curioo/curio-city']);

  const realms = await api('GET', '/api/plugins/keycloak/realms/');
  assert.equal(realms.body.count, 1); // master skipped
  const realm = realms.body.results[0];
  assert.equal(realm.name, 'curioo');
  assert.equal(realm.server.id, serverId); // FK expanded to a nested brief
  assert.equal(realm.client_count, 1); // built-ins filtered
  curiooRealmId = realm.id;

  const clients = await api('GET', `/api/plugins/keycloak/clients/?realm=${curiooRealmId}`);
  assert.equal(clients.body.count, 1);
  const client = clients.body.results[0];
  assert.equal(client.name, 'curio-city');
  assert.equal(client.secret, 'pre-existing-secret'); // fetched at discovery
  assert.equal(client.realm.id, curiooRealmId);
  curioClientRowId = client.id;
});

test('the client pre-existing URIs are mirrored locally', async () => {
  const urls = await api('GET', `/api/plugins/keycloak/redirect-urls/?client=${curioClientRowId}`);
  const byKind = Object.groupBy(urls.body.results, (u) => u.kind.value);
  assert.deepEqual(
    byKind.callback.map((u) => u.name),
    ['https://old.example.com/cb'],
  );
  assert.deepEqual(
    byKind.post_logout.map((u) => u.name),
    ['https://old.example.com'],
  );
});

test('creating a Realm really creates it in Keycloak', async () => {
  const r = await api('POST', '/api/plugins/keycloak/realms/', {
    server: serverId,
    name: 'staging',
  });
  assert.equal(r.status, 201);
  assert.equal(r.body.name, 'staging');
  newRealmId = r.body.id;
  assert.ok(kcState.realms.includes('staging')); // really created in Keycloak
});

test('creating a Client creates a confidential OIDC client with a stored secret', async () => {
  const c = await api('POST', '/api/plugins/keycloak/clients/', {
    realm: newRealmId,
    name: 'my-app',
  });
  assert.equal(c.status, 201);
  assert.equal(c.body.name, 'my-app');
  assert.match(c.body.secret, /^generated-secret-/); // Keycloak generated it, we stored it
  newClientRowId = c.body.id;

  // really created in Keycloak, confidential with the auth flow enabled
  const kcClient = kcState.clients.staging.find((x) => x.clientId === 'my-app');
  assert.ok(kcClient);
  assert.equal(kcClient.protocol, 'openid-connect');
  assert.equal(kcClient.publicClient, false);
  assert.equal(kcClient.standardFlowEnabled, true);
});

test('regenerate-secret fetches and stores a fresh secret', async () => {
  const r = await api('POST', `/api/plugins/keycloak/clients/${newClientRowId}/regenerate-secret/`);
  assert.equal(r.status, 200);
  assert.match(r.body.secret, /^regenerated-/);
  const c = await api('GET', `/api/plugins/keycloak/clients/${newClientRowId}/`);
  assert.equal(c.body.secret, r.body.secret); // stored locally too
});

test('renaming a Client propagates to Keycloak', async () => {
  const r = await api('PATCH', `/api/plugins/keycloak/clients/${newClientRowId}/`, {
    name: 'my-app-v2',
  });
  assert.equal(r.status, 200);
  assert.equal(r.body.name, 'my-app-v2');
  assert.ok(kcState.clients.staging.some((x) => x.clientId === 'my-app-v2'));
  assert.ok(!kcState.clients.staging.some((x) => x.clientId === 'my-app'));
});

test('register/ pushes callback + post-logout URLs to Keycloak (idempotent)', async () => {
  const INSTANCE = {
    url: 'monpc-e2e.localhost', // scheme omitted on purpose: https:// must be added
    realm: 'curioo',
    client_id: 'curio-city',
    callback_path: '/api/auth/callback',
  };
  const r = await api('POST', '/api/plugins/keycloak/redirect-urls/register/', INSTANCE);
  assert.equal(r.status, 200);
  assert.deepEqual(
    r.body.urls.map((u) => [u.kind, u.url]),
    [
      ['callback', 'https://monpc-e2e.localhost/api/auth/callback'],
      ['post_logout', 'https://monpc-e2e.localhost'], // no postlogout_path → bare URL
    ],
  );

  // really written to Keycloak (the stand-in's state)
  const kcClient = clientByUuid('curioo', 'uuid-curio');
  assert.ok(kcClient.redirectUris.includes('https://monpc-e2e.localhost/api/auth/callback'));
  assert.ok(kcClient.attributes[POST_LOGOUT_ATTR].includes('https://monpc-e2e.localhost'));

  // idempotent: no duplicates on a second call
  const urisBefore = kcClient.redirectUris.length;
  await api('POST', '/api/plugins/keycloak/redirect-urls/register/', INSTANCE);
  assert.equal(kcClient.redirectUris.length, urisBefore);

  // and unregister removes both again
  const u = await api('POST', '/api/plugins/keycloak/redirect-urls/unregister/', INSTANCE);
  assert.equal(u.status, 200);
  assert.ok(!kcClient.redirectUris.includes('https://monpc-e2e.localhost/api/auth/callback'));
});

test('register/ rejects an incomplete body and reports unknown targets', async () => {
  const bad = await api('POST', '/api/plugins/keycloak/redirect-urls/register/', {
    url: 'https://x.localhost',
    realm: 'curioo',
  });
  assert.equal(bad.status, 400);
  assert.match(bad.body.error, /client_id/);

  const skipped = await api('POST', '/api/plugins/keycloak/redirect-urls/register/', {
    url: 'https://x.localhost',
    realm: 'curioo',
    client_id: 'nope',
    callback_path: '/cb',
  });
  assert.equal(skipped.status, 200);
  assert.match(skipped.body.skipped, /not configured/);
});

test('the mirror follows Keycloak on reads', async () => {
  // an operator removes a redirect URI directly in Keycloak…
  clientByUuid('curioo', 'uuid-curio').redirectUris = [];
  const urls = await api('GET', `/api/plugins/keycloak/redirect-urls/?client=${curioClientRowId}`);
  // …the local mirror drops it on the next read (post-logout one remains)
  assert.deepEqual(
    urls.body.results.map((u) => u.kind.value),
    ['post_logout'],
  );
});

test('deleting a Client removes it from Keycloak and locally (URLs cascade)', async () => {
  const del = await api('DELETE', `/api/plugins/keycloak/clients/${newClientRowId}/`);
  assert.equal(del.status, 204);
  assert.ok(!kcState.clients.staging.some((x) => x.clientId === 'my-app-v2'));
  const rows = await db.get('SELECT COUNT(*) AS n FROM plugin_keycloak_client WHERE id = ?', [
    newClientRowId,
  ]);
  assert.equal(rows.n, 0);
});

test('deleting a Realm removes it from Keycloak and locally', async () => {
  const del = await api('DELETE', `/api/plugins/keycloak/realms/${newRealmId}/`);
  assert.equal(del.status, 204);
  assert.ok(!kcState.realms.includes('staging'));
});

test('deleting the Server only removes the local mirror', async () => {
  const del = await api('DELETE', `/api/plugins/keycloak/servers/${serverId}/`);
  assert.equal(del.status, 204);
  const realms = await db.get('SELECT COUNT(*) AS n FROM plugin_keycloak_realm');
  const clients = await db.get('SELECT COUNT(*) AS n FROM plugin_keycloak_client');
  const urls = await db.get('SELECT COUNT(*) AS n FROM plugin_keycloak_redirect_url');
  assert.equal(realms.n + clients.n + urls.n, 0); // local cascade
  assert.ok(kcState.realms.includes('curioo')); // Keycloak untouched
});
